package kube

import "kubebench/internal/reason"

// Reasons of the operations KubeBench refuses itself (OpError, EditError,
// ManifestError, RequestError; docs/design-v0.5.md §3.3). Parameters named
// detail carry Kubernetes' own (English) validation messages.
var (
	reasonNamespaceName      = reason.Define("namespace.invalid_name", "namespace name \"{{name}}\": {{detail}}")
	reasonNamespaceLabels    = reason.Define("namespace.invalid_labels", "{{detail}}")
	reasonNamespaceRequired  = reason.Define("namespace.name_required", "a namespace name is required")
	reasonNamespaceSystem    = reason.Define("namespace.system", "{{name}} is a system namespace; KubeBench deletes it only when forced")
	reasonNamespaceOwn       = reason.Define("namespace.own", "{{name}} is the namespace KubeBench runs in; KubeBench deletes it only when forced")
	reasonRestartKind        = reason.Define("workload.restart_kind", "only a Deployment, StatefulSet or DaemonSet can be restarted, not \"{{kind}}\"")
	reasonScaleKind          = reason.Define("workload.scale_kind", "{{kind}} cannot be scaled: it has no scale subresource")
	reasonReplicasNegative   = reason.Define("workload.replicas_negative", "replicas must be at least 0")
	reasonRolloutPaused      = reason.Define("rollout.paused", "Deployment {{name}} is paused; resume it before rolling back")
	reasonRolloutNoRevision  = reason.Define("rollout.no_revision", "Deployment {{name}} has no revision {{revision}}")
	reasonRolloutCurrent     = reason.Define("rollout.current_revision", "revision {{revision}} is the current revision of Deployment {{name}}")
	reasonBulkDeleteCount    = reason.Define("pod.bulk_delete_count", "a bulk delete takes 1 to {{max}} pods, not {{count}}")
	reasonBulkDeleteName     = reason.Define("pod.bulk_delete_name", "every pod needs a namespace and a name")
	reasonDebugImageSpace    = reason.Define("pod.debug_image_space", "the image \"{{image}}\" contains white space")
	reasonDebugNoContainer   = reason.Define("pod.debug_no_container", "pod {{pod}} has no container \"{{container}}\" to target")
	reasonDebugEnded         = reason.Define("pod.debug_ended", "the debug container {{container}} ended (exit code {{exitCode}}, {{detail}}) before a terminal could attach")
	reasonDebugCannotStart   = reason.Define("pod.debug_cannot_start", "the debug container {{container}} cannot start: {{detail}}")
	reasonDebugNoStatus      = reason.Define("pod.debug_no_status", "the debug container {{container}} is not running after {{timeout}}: it has no status yet")
	reasonDebugNotRunning    = reason.Define("pod.debug_not_running", "the debug container {{container}} is not running after {{timeout}}: {{detail}}")
	reasonNamespaceIgnored   = reason.Define("apply.namespace_ignored", "{{kind}} is cluster-scoped: metadata.namespace \"{{namespace}}\" was ignored")
	reasonNotTerminated      = reason.Define("drain.not_terminated", "evicted, but the pod had not terminated when the drain ended")
	reasonNotEvicted         = reason.Define("drain.not_evicted", "not evicted before the drain ended")
	reasonTaintKey           = reason.Define("node.taint_key", "taint {{index}}: key \"{{key}}\": {{detail}}")
	reasonTaintValue         = reason.Define("node.taint_value", "taint \"{{key}}\": value \"{{value}}\": {{detail}}")
	reasonTaintEffect        = reason.Define("node.taint_effect", "taint \"{{key}}\": effect must be NoSchedule, PreferNoSchedule or NoExecute, not \"{{effect}}\"")
	reasonTaintDuplicate     = reason.Define("node.taint_duplicate", "taint \"{{key}}\" with effect {{effect}} is listed twice")
	reasonNeedsPrometheus    = reason.Define("metrics.needs_prometheus", "metrics-server has no {{metric}} data; it needs Prometheus")
	reasonPodMetric          = reason.Define("metrics.pod_metric", "metric \"{{metric}}\" is not available for pods")
	reasonCannotResolve      = reason.Define("watch.cannot_resolve", "cannot resolve {{topic}}: {{detail}}")
	reasonNamespacedKind     = reason.Define("resource.namespaced_kind", "{{kind}} is a namespaced kind: name its namespace")
	reasonManifestYAML       = reason.Define("manifest.invalid_yaml", "document {{document}}: not valid YAML or JSON: {{detail}}")
	reasonManifestNotObject  = reason.Define("manifest.not_object", "document {{document}}: not an object")
	reasonManifestAPIVersion = reason.Define("manifest.api_version_required", "document {{document}}: apiVersion is required")
	reasonManifestKind       = reason.Define("manifest.kind_required", "document {{document}}: kind is required")
	reasonManifestName       = reason.Define("manifest.name_required", "document {{document}}: {{kind}}: metadata.name is required (server-side apply cannot generate names)")
	reasonManifestRedacted   = reason.Define("manifest.secret_placeholder", "document {{document}}: Secret {{name}}: {{field}} holds a redaction placeholder, not its value; reveal the Secret and use the real values")
	reasonManifestAnnotation = reason.Define("manifest.secret_annotation_placeholder", "document {{document}}: Secret {{name}}: the {{annotation}} annotation holds a redaction placeholder; remove the annotation")
	reasonEditYAML           = reason.Define("edit.invalid_yaml", "the edited manifest is not valid YAML or JSON: {{detail}}")
	reasonEditDocuments      = reason.Define("edit.several_documents", "the edited manifest holds more than one document; edit one object at a time")
	reasonEditNotObject      = reason.Define("edit.not_object", "the edited manifest is not an object")
	reasonEditEmpty          = reason.Define("edit.empty", "the edited manifest is empty")
	reasonEditOtherObject    = reason.Define("edit.other_object", "the edited manifest describes {{kind}} {{name}}, not the edited {{edited}}; create other objects with New resource")
	reasonOriginalYAML       = reason.Define("edit.original_invalid_yaml", "the original manifest is not valid YAML or JSON: {{detail}}")
	reasonOriginalDocuments  = reason.Define("edit.original_several_documents", "the original manifest holds more than one document; edit one object at a time")
	reasonOriginalNotObject  = reason.Define("edit.original_not_object", "the original manifest is not an object")
	reasonOriginalEmpty      = reason.Define("edit.original_empty", "the original manifest is empty")
	reasonOriginalOther      = reason.Define("edit.original_other_object", "the original manifest describes {{kind}} {{name}}, not the edited {{edited}}; create other objects with New resource")
	reasonEditRedacted       = reason.Define("edit.secret_placeholder", "Secret {{name}}: {{field}} is set to a redaction placeholder; leave the placeholder unchanged to keep the value, or enter the real value")
	reasonEditAnnotation     = reason.Define("edit.secret_annotation_placeholder", "Secret {{name}}: the {{annotation}} annotation holds a redaction placeholder; remove the annotation")
	// The credential kinds' (credentials.go) counterparts of the Secret refusals.
	reasonManifestCredential           = reason.Define("manifest.credential_placeholder", "document {{document}}: {{kind}} {{name}}: {{field}} holds a redaction placeholder, not its value; use the real value")
	reasonManifestCredentialAnnotation = reason.Define("manifest.credential_annotation_placeholder", "document {{document}}: {{kind}} {{name}}: the {{annotation}} annotation holds a redaction placeholder; remove the annotation")
	reasonEditCredential               = reason.Define("edit.credential_placeholder", "{{kind}} {{name}}: {{field}} is set to a redaction placeholder; leave it and the list holding it unchanged to keep the value, or enter the real value")
	reasonEditCredentialAnnotation     = reason.Define("edit.credential_annotation_placeholder", "{{kind}} {{name}}: the {{annotation}} annotation holds a redaction placeholder; remove the annotation")
)
